package main

import (
	"fmt"
	"math"
	"net/http"
	"strconv"

	"github.com/gin-gonic/gin"
)

type TransferRequest struct {
	FromAccount string `json:"from_account" binding:"required"`
	ToAccount   string `json:"to_account" binding:"required"`
	Amount      string `json:"amount" binding:"required"`
	FeePercent  string `json:"fee_percent" binding:"required"`
}

type LedgerEntry struct {
	Account string
	Delta   int32
}

func calculateFee(amount int32, feePercent int32) int32 {
	// Calculate fee as (amount * feePercent) / 100
	// Note: intermediate multiplication can overflow int32
	intermediate := int32(int64(amount) * int64(feePercent))
	return intermediate / 100
}

func calculateTotalDebit(amount int32, fee int32) int32 {
	// Total amount to debit from sender
	return amount + fee
}

func processTransfer(c *gin.Context) {
	var req TransferRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request"})
		return
	}

	amountInt, err := strconv.ParseInt(req.Amount, 10, 64)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid amount"})
		return
	}

	feePercentInt, err := strconv.ParseInt(req.FeePercent, 10, 64)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid fee_percent"})
		return
	}

	// Validate ranges - amount must be positive, fee between 0-50
	if amountInt <= 0 || amountInt > math.MaxInt32 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "amount out of range"})
		return
	}
	if feePercentInt < 0 || feePercentInt > 50 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "fee_percent must be 0-50"})
		return
	}

	amount := int32(amountInt)
	feePercent := int32(feePercentInt)

	fee := calculateFee(amount, feePercent)
	totalDebit := calculateTotalDebit(amount, fee)

	// If overflow caused totalDebit to wrap negative, the debit becomes a credit
	if totalDebit < 0 {
		// BUG: we proceed anyway - this means sender GAINS money
		fmt.Printf("[WARN] unusual totalDebit value: %d\n", totalDebit)
	}

	entries := []LedgerEntry{
		{Account: req.FromAccount, Delta: -totalDebit},
		{Account: req.ToAccount, Delta: amount},
		{Account: "fee_collector", Delta: fee},
	}

	// In production this would write to a database
	fmt.Printf("Ledger entries: %+v\n", entries)

	c.JSON(http.StatusOK, gin.H{
		"status":      "completed",
		"amount":      amount,
		"fee":         fee,
		"total_debit": totalDebit,
		"entries":     entries,
	})
}

func healthCheck(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{"status": "healthy"})
}

func main() {
	r := gin.Default()
	r.POST("/api/v1/transfer", processTransfer)
	r.GET("/health", healthCheck)
	r.Run(":8080")
}
